function Test-PathContains {
    param(
        [AllowNull()]
        [string] $PathValue,
        [string] $Directory
    )

    if ([string]::IsNullOrWhiteSpace($PathValue)) {
        return $false
    }

    foreach ($entry in ($PathValue -split ";")) {
