    $nightlies = New-Object System.Collections.Generic.List[object]
    $page = 1
    while ($page -le 10) {
        $uri = "https://api.github.com/repos/$GitHubRepo/releases?per_page=100&page=$page"
        $batch = Invoke-GitHubApi -Uri $uri
        $batchCount = 0
        foreach ($candidate in $batch) {
            $batchCount++
            if ($candidate.tag_name -like "*nightly*") {
                $nightlies.Add($candidate)
            }
        }
        if ($nightlies.Count -gt 0 -or $batchCount -lt 100) {
            break
        }
        $page++
    }

    $latest = $null
    $latestStamp = ""
    foreach ($candidate in $nightlies) {
        $stamp = [string] $candidate.published_at
        if ([string]::IsNullOrWhiteSpace($stamp)) {
            $stamp = [string] $candidate.created_at
        }
        if ($null -eq $latest -or [string]::CompareOrdinal($stamp, $latestStamp) -gt 0) {
            $latest = $candidate
            $latestStamp = $stamp
        }
    }
    return $latest
}

function Get-ReleaseVersion {
    param([string] $ReleaseChannel)

    if ($ReleaseChannel -eq "nightly") {
        $release = Get-LatestNightlyRelease
    }
    else {
        $uri = "https://api.github.com/repos/$GitHubRepo/releases/latest"
        $release = Invoke-GitHubApi -Uri $uri
    }
